  "implementation": "def solve(case):
    lines = case['lines']
    trajectory = []
    valid = True
    error_line = None
    state = 'START'  # states: START, THOUGHT, ACTION, ACTION_INPUT, OBSERVATION, FINAL
    # Map prefixes to types
    prefix_type = [
        ('Thought:', 'thought'),
        ('Action:', 'action'),
        ('Action Input:', 'action_input'),
        ('Observation:', 'observation'),
        ('Final:', 'final')
    ]
    for idx, line in enumerate(lines, start=1):
        # Determine record type
        rec_type = None
        for prefix, t in prefix_type:
            if line.startswith(prefix):
                rec_type = t
                # content is text after prefix, stripped
                content = line[len(prefix):].strip()
                break
        if rec_type is None:
            # invalid line
            valid = False
            error_line = idx
            break
        # Validate state transition
        if state == 'START':
            if rec_type in ('thought', 'final'):
                if rec_type == 'thought':
                    state = 'THOUGHT'
                else:  # final
                    state = 'FINAL'
            else:
                valid = False
                error_line = idx
                break
        elif state == 'THOUGHT':
            if rec_type == 'action':
                state = 'ACTION'
            else:
                valid = False
                error_line = idx
                break
        elif state == 'ACTION':
            if rec_type == 'action_input':
                state = 'ACTION_INPUT'
            elif rec_type == 'observation':
                state = 'OBSERVATION'
            else:
                valid = False
                error_line = idx
                break
        elif state == 'ACTION_INPUT':
            if rec_type == 'observation':
                state = 'OBSERVATION'
            else:
                valid = False
                error_line = idx
                break
        elif state == 'OBSERVATION':
            if rec_type == 'thought':
                state = 'THOUGHT'
            elif rec_type == 'final':
                state = 'FINAL'
            else:
                valid = False
                error_line = idx
                break
        elif state == 'FINAL':
            # No further records allowed after final
            valid = False
            error_line = idx
            break
        # Add to trajectory
        trajectory.append({'type': rec_type, 'content': content})
    else:
        # Loop completed without break
        if state != 'FINAL':
            # Missing Final at end
            valid = False
            error_line = len(lines) + 1
            # trajectory already contains all records
    if valid:
        return {'valid': True, 'error_line': None, 'trajectory': trajectory}
    else:
        # error_line is set, trajectory contains valid prefix (excluding violating line)
        return {'valid': False, 'error_line': error_line, 'trajectory': trajectory[:error_line-1 if error_line <= len(lines) else len(trajectory)]}
